/// <summary>
/// Bug 373641: E2E - Supply - CB705 Migrated Vendor rebates needs to be in approved state
/// </summary>
class METTAMRebateDealWorkflowSubmitService extends SysOperationServiceBase
{    
}

Method.Source:
/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract"><c>METTAMRebateDealWorkflowSubmitContract</c> object</param>
void process(METTAMRebateDealWorkflowSubmitContract _contract)
{
    #OCCRetryCount
    TAMRebateDeal rebateDeal;
    QueryRun qr = new QueryRun(_contract.getQuery());

    WorkflowVersionTable workflowVersionTable;

    while (qr.next())   
    {
        try
        {
            ttsbegin;
            rebateDeal = qr.get(tableNum(TAMRebateDeal));

            if (rebateDeal.canSubmitToWorkflow())
            {                
                if (rebateDeal.METVolumetricTierDeal
                && (!TAMRebateTable::existByTierType(rebateDeal.RecId, METTierLineType::Rate)
                ||  !TAMRebateTable::existByTierType(rebateDeal.RecId, METTierLineType::Value)))
                {
                    throw error("@MET:VolRebateWorkFlowErrorMessage");
                }                    

                workflowVersionTable = Workflow::findWorkflowConfigToActivateForType(workFlowTypeStr(TAMRebateDeal),
                                                                                     rebateDeal.recId,
                                                                                     rebateDeal.TableId);
                if (workflowVersionTable)
                {
                    Workflow::activateFromWorkflowConfigurationId(
                        workflowVersionTable.ConfigurationId,
                        rebateDeal.RecId,
                        "@MET:RebateDealsWorkflowComment",
                        false);

                    rebateDeal.selectForUpdate(true);
                    rebateDeal.State = TAMRebateDealWorkflowState::Submitted;
                    rebateDeal.update();
                }
            }

            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            Global::exceptionTextFallThrough();
        }
    }
}
